use std::{env, process};
use test_programs::preview1::open_scratch_directory;

const FILENAME: &str = "test.txt";
const EXPECTED: &[u8] = b"truncation test file\n";

/// Open `FILENAME` for reading and return its full contents.
unsafe fn read_file_contents(dir_fd: wasip1::Fd) -> Vec<u8> {
    let file_fd = wasip1::path_open(
        dir_fd,
        0,
        FILENAME,
        0,
        wasip1::RIGHTS_FD_READ,
        0,
        0,
    )
    .expect("opening the file for reading");

    let mut contents = Vec::new();
    let mut buffer = [0u8; 128];
    loop {
        let nread = wasip1::fd_read(
            file_fd,
            &[wasip1::Iovec {
                buf: buffer.as_mut_ptr(),
                buf_len: buffer.len(),
            }],
        )
        .expect("reading file content");
        if nread == 0 {
            break;
        }
        contents.extend_from_slice(&buffer[..nread]);
    }

    wasip1::fd_close(file_fd).expect("closing the file");
    contents
}

unsafe fn test_file_truncation_readonly(dir_fd: wasip1::Fd) {
    // The file should have its expected contents before we do anything.
    assert_eq!(
        read_file_contents(dir_fd),
        EXPECTED,
        "file contents before truncation attempt"
    );

    // Attempting to open the file with the truncation flag while only holding
    // read rights must be rejected as not permitted.
    let err = wasip1::path_open(
        dir_fd,
        0,
        FILENAME,
        wasip1::OFLAGS_TRUNC,
        wasip1::RIGHTS_FD_READ,
        0,
        0,
    )
    .expect_err("truncating a read-only file must fail");
    assert_eq!(
        err,
        wasip1::ERRNO_PERM,
        "expected ERRNO_PERM when truncating without write permission"
    );

    // The failed truncation attempt must not have modified the file.
    assert_eq!(
        read_file_contents(dir_fd),
        EXPECTED,
        "file contents after failed truncation attempt"
    );
}

fn main() {
    let mut args = env::args();
    let prog = args.next().unwrap();
    let arg = if let Some(arg) = args.next() {
        arg
    } else {
        eprintln!("usage: {prog} <scratch directory>");
        process::exit(1);
    };

    // Open scratch directory
    let dir_fd = match open_scratch_directory(&arg) {
        Ok(dir_fd) => dir_fd,
        Err(err) => {
            eprintln!("{err}");
            process::exit(1)
        }
    };

    // Run the tests.
    unsafe { test_file_truncation_readonly(dir_fd) }
